func renderExecuteQueue(currentTaskID string, queue []ExecutePlanTask) string {
	if len(queue) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("\n## Ordered Sprint Execution Queue\n\n")
	b.WriteString("This agent session owns the complete ordered queue below. Execute only the current task during this turn; UltraPlan will checkpoint its evidence before advancing the same session.\n\n")
	for index, task := range queue {
		marker := "queued"
		if task.ID == currentTaskID {
			marker = "current"
		}
		fmt.Fprintf(&b, "%d. [%s] `%s` — %s\n", index+1, marker, task.ID, task.Name)
	}
	return b.String()
}

func filterExecuteQueue(tasks []ExecutePlanTask, taskID string) []ExecutePlanTask {
	if taskID == "" {
		return append([]ExecutePlanTask(nil), tasks...)
	}
	selected := taskByID(tasks, taskID)
	if selected.ID == "" {
		return nil
	}
	return []ExecutePlanTask{selected}
}

func executeQueueFromState(records []ExecuteTaskRecord, tasks []ExecutePlanTask, taskID string) []ExecutePlanTask {
	queue := make([]ExecutePlanTask, 0, len(records))
	for _, record := range records {
		if taskID != "" && record.ID != taskID {
			continue
		}
		if record.Status == ExecuteTaskComplete || record.Status == ExecuteTaskDeferred {
			continue
		}
		if task := taskByID(tasks, record.ID); task.ID != "" {
			queue = append(queue, task)
		}
	}
	return queue
}

func reusableExecuteSession(records []ExecuteTaskRecord, taskID, model string) string {
	sessionID := ""
	for _, record := range records {
		if taskID != "" && record.ID != taskID {
			continue
		}
		if record.Runtime != nil && record.Runtime.Model == model && record.Runtime.SessionID != "" {
			sessionID = record.Runtime.SessionID
		}
	}
	return sessionID
}

func WriteExecuteSummary(root string, sp Sprint, state ExecuteRunState) error {
	path, err := resolveSprintContained(root, sp, ArtifactRelPath(sp, StageExecute))
	if err != nil {
		return err
	}
	var b strings.Builder
	fmt.Fprintf(&b, "# Execute Summary\n\nPlan: `%s`\nRun state: `%s`\n\n", state.PlanPath, ExecuteRunStateRelPath(sp))
	counts := map[ExecuteTaskStatus]int{}
	for _, task := range state.Tasks {
		counts[task.Status]++
	}
	fmt.Fprintln(&b, "## Task Counts")
	fmt.Fprintln(&b)
	for _, status := range ExecuteTaskStatuses() {
		fmt.Fprintf(&b, "- %s: %d\n", status, counts[status])
	}
	fmt.Fprintln(&b, "\n## Tasks")
	fmt.Fprintln(&b)
	for _, task := range state.Tasks {
		fmt.Fprintf(&b, "- `%s` %s: %s (attempts: %d)\n", task.ID, task.Status, task.Identity.Name, task.Attempts)
		for _, evidence := range task.Evidence {
			fmt.Fprintf(&b, "  - evidence: %s %s\n", evidence.Kind, evidence.Summary)
		}
		for _, diagnostic := range task.Diagnostics {
			fmt.Fprintf(&b, "  - diagnostic: %s %s\n", diagnostic.Code, diagnostic.Message)
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(b.String()), 0o644)
}

func ArtifactExecuteRelPath(s Sprint) string { return ArtifactRelPath(s, StageExecute) }

func taskByID(tasks []ExecutePlanTask, id string) ExecutePlanTask {
	for _, task := range tasks {
		if task.ID == id {
			return task
		}
	}
	return ExecutePlanTask{}
}

func reconcileExecuteState(existing ExecuteRunState, planned []ExecuteTaskRecord, now time.Time) ExecuteRunState {
	byID := map[string]ExecuteTaskRecord{}
	for _, task := range existing.Tasks {
		if task.Status == ExecuteTaskRunning {
			task.Status = ExecuteTaskFailed
			task.CompletedAt = &now
			task.Diagnostics = append(task.Diagnostics, ExecuteDiagnostic{Code: "stale-running", Message: "recovered stale running task on resume", At: now})
		}
		byID[task.ID] = task
	}
	for i, task := range planned {
		if old, ok := byID[task.ID]; ok {
			planned[i] = old
		}
	}
	existing.Tasks = planned
	existing.UpdatedAt = now
	return existing
}

func runtimeSummary(run pruntime.Result, selection ExecuteModelSelection) *ExecuteRuntimeSummary {
	return &ExecuteRuntimeSummary{RunID: run.RunID, SessionID: run.SessionID, Model: selection.Model, ModelSource: selection.Source, PermissionSummary: run.Permissions.Mode, ValidationSummary: fmt.Sprintf("configured=%t passed=%t failures=%d", run.Validation.Configured, run.Validation.Passed, run.Validation.Failures), UsageSummary: formatRuntimeUsage(run.Usage), OmissionReason: "raw runtime payloads omitted"}
}

func formatRuntimeUsage(usage pruntime.Usage) string {
	var parts []string
	appendKnown := func(name string, known bool, value int64) {
		if known {
			parts = append(parts, fmt.Sprintf("%s=%d", name, value))
		}
	}
	appendKnown("input", usage.InputTokensKnown, usage.InputTokens)
	appendKnown("output", usage.OutputTokensKnown, usage.OutputTokens)
	appendKnown("reasoning", usage.ReasoningTokensKnown, usage.ReasoningTokens)
	appendKnown("cache_read", usage.CacheReadTokensKnown, usage.CacheReadTokens)
	appendKnown("cache_write", usage.CacheWriteTokensKnown, usage.CacheWriteTokens)
	appendKnown("total", usage.TotalTokensKnown, usage.TotalTokens)
	appendKnown("turns", usage.TurnsKnown, usage.Turns)
	return strings.Join(parts, " ")
}

func mergeRuntimeSummary(previous, current *ExecuteRuntimeSummary) *ExecuteRuntimeSummary {
	if current == nil {
		return previous
	}
	if current.SessionID == "" && previous != nil {
		current.SessionID = previous.SessionID
	}
	return current
}

func hasDiagnosticOnlyCompletion(run pruntime.Result) bool {
	for _, warning := range run.Warnings {
		if strings.Contains(strings.ToLower(warning), "diagnostic-only") {
			return true
		}
	}
	return false
}

func safeArtifactPath(uri string) string {
	if safeRelPath(uri) {
		return uri
	}
	return ""
}

func ptrTime(t time.Time) *time.Time { return &t }

func firstNonEmptyString(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return "runtime artifact"
}

func mustReadPlan(s Service, sp Sprint) string {
	data, _ := s.store.ReadArtifact(sp, StagePlan)
	return data
}

func executeResultMessage(tasks []ExecuteTaskRecord) string {
	if hasFailedExecuteTask(tasks) {
		return "execute failed"
	}
	return "execute complete"
}

func (s Service) executeModelSelection(override string) ExecuteModelSelection {
	if strings.TrimSpace(override) != "" {
		return ExecuteModelSelection{Model: override, Source: "command override"}
	}
	if rt, ok := s.stageRuntime[StageExecute]; ok && strings.TrimSpace(rt.Model) != "" {
		return ExecuteModelSelection{Model: rt.Model, Source: "planning.execute_model"}
	}
	if rt, ok := s.stageRuntime[StagePlan]; ok && strings.TrimSpace(rt.Model) != "" {
		return ExecuteModelSelection{Model: rt.Model, Source: "planning.plan_model"}
	}
	if model := joinProviderModel(s.runtimeConfig.Provider, s.runtimeConfig.Model); model != "" {
		return ExecuteModelSelection{Model: model, Source: "runtime.config"}
	}
	return ExecuteModelSelection{Model: "unresolved", Source: "unresolved"}
}

func joinProviderModel(provider, model string) string {
	if strings.TrimSpace(model) == "" {
		return ""
	}
	if strings.TrimSpace(provider) == "" {
		return model
	}
	return provider + "/" + model
}

// executeSelectionForTask resolves one task's effective model selection. An
// inline plan annotation wins over the batch selection; defaults stay
// unchanged when no annotation is present.
func executeSelectionForTask(selection ExecuteModelSelection, task ExecutePlanTask) ExecuteModelSelection {
	if model := strings.TrimSpace(task.Model); model != "" {
		return ExecuteModelSelection{Model: model, Source: "plan.md task annotation"}
	}
	return selection
}

func safeExecuteText(key, value string) string {
	return config.RedactValue(key, safeError(fmt.Errorf("%s", value)))
}

func hasFailedExecuteTask(tasks []ExecuteTaskRecord) bool {
	for _, task := range tasks {
		if task.Status == ExecuteTaskFailed || task.Status == ExecuteTaskCancelled {
			return true
		}
	}
	return false
}

func allExecuteTasksResolved(tasks []ExecuteTaskRecord) bool {
	if len(tasks) == 0 {
		return false
	}
	for _, task := range tasks {
		if task.Status != ExecuteTaskComplete && task.Status != ExecuteTaskDeferred {
			return false
		}
	}
	return true
}

package sprint

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"time"
)

type ExecutePlanTask struct {
	ID           string
	Name         string
	PlanLine     int
	Checked      bool
	Deferred     bool
	DeferReason  string
	Steps        []string
	Decisions    []string
	Requirements []string
	Evidence     []string
	// Model optionally overrides the runtime model (provider/model) for this
	// task via an inline `<!-- model: provider/model -->` plan annotation.
	Model string
}

func ExtractExecutePlanTasks(content string, manifest PlanManifest) ([]ExecutePlanTask, []ValidationFinding) {
	return extractExecutePlanTasks(content, manifest, false)
}

func extractExecutePlanTasks(content string, manifest PlanManifest, allowChecked bool) ([]ExecutePlanTask, []ValidationFinding) {
	var findings []ValidationFinding
	planFindings := ValidatePlanContent(content, manifest)
	if len(planFindings) > 0 {
		return nil, planFindings
	}
	taskSection := markdownSections(content)["Tasks"]
	if strings.TrimSpace(taskSection) == "" {
		return nil, []ValidationFinding{finding("Tasks", "", manifest.OutputPath, "missing tasks section", "plan has no Tasks section", "Add explicit top-level task checklist entries.")}
	}
	lines := strings.Split(taskSection, "\n")
	var tasks []ExecutePlanTask
	var current *ExecutePlanTask
	flush := func() {
		if current == nil {
			return
		}
		current.Decisions = uniqueSorted(current.Decisions)
		current.Requirements = uniqueSorted(current.Requirements)
		current.Evidence = uniqueSorted(current.Evidence)
		current.Steps = uniqueStable(current.Steps)
		current.ID = deterministicExecuteTaskID(*current)
		tasks = append(tasks, *current)
		current = nil
	}
	baseLine := sectionStartLine(content, "Tasks")
	for i, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if isTopLevelTaskCheckbox(line) {
			flush()
			title, checked, ok, taskModel := parseTopLevelTaskLine(line)
			deferred := isDeferredTaskLine(line)
			deferReason := deferredTaskReason(line)
			if !ok {
				findings = append(findings, finding("Tasks", "", manifest.OutputPath, "unsupported task syntax", strings.TrimSpace(line), "Use '- [ ] Task N: Name' or '- [ ] **Task N: Name**'."))
				continue
			}
			if checked {
				if !allowChecked {
					findings = append(findings, finding("Tasks", title, manifest.OutputPath, "completed task cannot be executed", "top-level task is already checked", "Leave executable plan tasks unchecked until execute records completion."))
				}
			}
			if deferred {
				if deferReason == "" {
					findings = append(findings, finding("Tasks", title, manifest.OutputPath, "deferred task lacks rationale", "top-level task uses [/] without an inline Deferred reason", "Use '- [/] Task N: Name — Deferred: concrete reason'."))
				}
				if !allowChecked {
					findings = append(findings, finding("Tasks", title, manifest.OutputPath, "deferred task cannot start a new execution", "top-level task is already marked deferred", "Start with [ ] and let execute record the agent's deferral, or resume the matching run state."))
				}
			}
			current = &ExecutePlanTask{Name: title, PlanLine: baseLine + i + 1, Checked: checked, Deferred: deferred, DeferReason: deferReason, Model: taskModel}
			current.Decisions = append(current.Decisions, extractRefs(title, `Decision\s+\d+`)...)
			current.Requirements = append(current.Requirements, extractRefs(title, `(?:REQ-\d+-\d+|AC-\d+)`)...)
			continue
		}
		if strings.HasPrefix(strings.TrimLeft(line, " \t"), "- [") {
			if current == nil {
				findings = append(findings, finding("Tasks", "", manifest.OutputPath, "ambiguous checklist item", strings.TrimSpace(line), "Nested checklist items must appear under an explicit top-level Task entry."))
				continue
			}
			item := strings.TrimSpace(stripCheckbox(line))
			current.Steps = append(current.Steps, item)
			lower := strings.ToLower(item)
			if strings.Contains(lower, "evidence") || strings.Contains(lower, "verification") || strings.Contains(lower, "test") || strings.Contains(lower, "check") {
				current.Evidence = append(current.Evidence, item)
			}
			current.Decisions = append(current.Decisions, extractRefs(item, `Decision\s+\d+`)...)
			current.Requirements = append(current.Requirements, extractRefs(item, `(?:REQ-\d+-\d+|AC-\d+)`)...)
			continue
		}
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, ">") && current != nil {
			current.Decisions = append(current.Decisions, extractRefs(trimmed, `Decision\s+\d+`)...)
			current.Requirements = append(current.Requirements, extractRefs(trimmed, `(?:REQ-\d+-\d+|AC-\d+)`)...)
		}
	}
	flush()
	if len(findings) > 0 {
		sortSprintFindings(findings)
		return nil, findings
	}
	if len(tasks) == 0 {
		return nil, []ValidationFinding{finding("Tasks", "", manifest.OutputPath, "no executable tasks", "no supported unchecked top-level Task checklist entries were found", "Add explicit '- [ ] Task N: ...' entries.")}
	}
	seen := map[string]ExecutePlanTask{}
	for _, task := range tasks {
		if prior, ok := seen[task.ID]; ok {
			findings = append(findings, finding("Tasks", task.Name, manifest.OutputPath, "duplicate task id", fmt.Sprintf("%s duplicates %s", task.Name, prior.Name), "Make task identity fields distinct."))
		}
		seen[task.ID] = task
	}
	sortSprintFindings(findings)
	return tasks, findings
}

func PlanFingerprint(content string) string {
	sum := sha256.Sum256([]byte(normalizeTaskText(content)))
	return "sha256:" + hex.EncodeToString(sum[:])
}

func ExecuteTasksToRecords(tasks []ExecutePlanTask, now func() time.Time) []ExecuteTaskRecord {
	records := make([]ExecuteTaskRecord, 0, len(tasks))
	current := now()
	for _, task := range tasks {
		records = append(records, ExecuteTaskRecord{
			ID: task.ID,
			Identity: ExecuteTaskIdentity{
				Name:         task.Name,
				PlanLine:     task.PlanLine,
				Decisions:    task.Decisions,
				Requirements: task.Requirements,
				Evidence:     task.Evidence,
			},
			Status:    ExecuteTaskPending,
			Attempts:  0,
			CreatedAt: current,
			UpdatedAt: current,
		})
	}
	return records
}

func deterministicExecuteTaskID(task ExecutePlanTask) string {
	parts := []string{task.Name}
	parts = append(parts, task.Decisions...)
	parts = append(parts, task.Requirements...)
	parts = append(parts, task.Evidence...)
	sum := sha256.Sum256([]byte(normalizeTaskText(strings.Join(parts, "\n"))))
	return "task-" + hex.EncodeToString(sum[:])[:12]
}

// taskModelAnnotationPattern matches an inline per-task runtime model
// annotation, e.g. `- [ ] Task 1: Name <!-- model: provider/model -->`.
var taskModelAnnotationPattern = regexp.MustCompile(`(?i)<!--\s*model:\s*([A-Za-z0-9._~/-]+)\s*-->`)

func parseTopLevelTaskLine(line string) (string, bool, bool, string) {
	trimmed := strings.TrimSpace(line)
	checked := strings.HasPrefix(strings.ToLower(trimmed), "- [x]")
	body := strings.TrimSpace(trimmed[5:])
	body, _ = splitDeferredTaskReason(body)
	model := ""
	if match := taskModelAnnotationPattern.FindStringSubmatchIndex(body); match != nil {
		model = strings.TrimSpace(body[match[2]:match[3]])
		body = strings.TrimSpace(body[:match[0]] + body[match[1]:])
	}
	body = strings.Trim(body, "* ")
	if !regexp.MustCompile(`(?i)^Task\s+\d+\s*:`).MatchString(body) {
		return "", checked, false, model
	}
	body = strings.TrimSpace(strings.Trim(body, "* "))
	return body, checked, true, model
}

func isDeferredTaskLine(line string) bool {
	return strings.HasPrefix(strings.ToLower(strings.TrimSpace(line)), "- [/]")
}

func deferredTaskReason(line string) string {
	_, reason := splitDeferredTaskReason(strings.TrimSpace(line)[5:])
	return reason
}

func splitDeferredTaskReason(body string) (string, string) {
	re := regexp.MustCompile(`(?i)\s+(?:—|-)\s+deferred:\s*(.+?)\s*$`)
	match := re.FindStringSubmatchIndex(body)
	if match == nil {
		return body, ""
	}
	return strings.TrimSpace(body[:match[0]]), strings.TrimSpace(body[match[2]:match[3]])
}

func stripCheckbox(line string) string {
	trimmed := strings.TrimSpace(line)
	if len(trimmed) >= 5 && strings.HasPrefix(trimmed, "- [") {
		return strings.TrimSpace(trimmed[5:])
	}
	return trimmed
}

func extractRefs(text, pattern string) []string {
	re := regexp.MustCompile(`(?i)` + pattern)
	matches := re.FindAllString(text, -1)
	out := make([]string, 0, len(matches))
	for _, match := range matches {
		out = append(out, strings.TrimSpace(match))
	}
	return out
}

func sectionStartLine(content, section string) int {
	re := regexp.MustCompile(`(?m)^#{2,6}\s+` + regexp.QuoteMeta(section) + `\s*$`)
	loc := re.FindStringIndex(content)
	if loc == nil {
		return 0
	}
	return strings.Count(content[:loc[0]], "\n") + 1
}

func uniqueSorted(values []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		key := strings.ToLower(value)
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func uniqueStable(values []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		out = append(out, value)
	}
	return out
}

func normalizeTaskText(value string) string {
	fields := strings.Fields(strings.ToLower(value))
	return strings.Join(fields, " ")
}

package sprint

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

const sprintWorkspaceSchemaVersion = 1

type SprintWorkspace struct {
	SchemaVersion int       `json:"schemaVersion"`
	SourceRoot    string    `json:"sourceRoot"`
	Path          string    `json:"path"`
	Branch        string    `json:"branch"`
	Baseline      string    `json:"baseline"`
	CreatedAt     time.Time `json:"createdAt"`
}

func sprintWorkspacePath(sp Sprint) string { return filepath.Join(sp.Path, ".workspace.json") }

func ResolveExecuteTarget(workspaceRoot, projectIndexContent string) (ExecuteTargetRef, []ValidationFinding) {
	target := extractTargetImplementationDirectory(projectIndexContent)
	if target == "" {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", "", "missing target implementation directory", "project-index.md does not declare a target implementation directory", "Set Project Scope / Target Implementation Directory to the approved implementation repository.")}
	}
	clean := filepath.Clean(target)
	if !filepath.IsAbs(clean) {
		if strings.TrimSpace(workspaceRoot) == "" {
			return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "relative target has no workspace root", "the target cannot be resolved without the UltraPlan workspace root", "Run the command from a valid UltraPlan workspace or use an absolute target path.")}
		}
		clean = filepath.Join(workspaceRoot, clean)
	}
	resolved, err := filepath.Abs(clean)
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target path cannot be resolved", err.Error(), "Use a valid absolute path or a path relative to the UltraPlan workspace root.")}
	}
	clean = filepath.Clean(resolved)
	info, err := os.Stat(clean)
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target root unavailable", err.Error(), "Create or restore the approved target repository before execute.")}
	}
	if !info.IsDir() {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Project Scope", "Target Implementation Directory", target, "target root is not a directory", "path exists but is not a directory", "Use the approved target repository directory.")}
	}
	return ExecuteTargetRef{Path: clean, Source: "project-index.md"}, nil
}

func (s Service) resolveSprintTarget(sp Sprint, projectIndex string, create bool) (ExecuteTargetRef, []ValidationFinding) {
	if s.codeContextTarget != nil {
		return s.codeContextTarget(projectIndex)
	}
	source, findings := ResolveExecuteTarget(s.root, projectIndex)
	if len(findings) > 0 {
		return ExecuteTargetRef{}, findings
	}
	record, err := loadSprintWorkspace(sp)
	if err == nil {
		if validateErr := validateSprintWorkspace(record, source.Path); validateErr != nil {
			return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", workspace.Rel(s.root, sprintWorkspacePath(sp)), "invalid sprint workspace", validateErr.Error(), "Restore the recorded worktree or explicitly recreate the sprint workspace.")}
		}
		return ExecuteTargetRef{Path: record.Path, Source: ".workspace.json"}, nil
	}
	if !os.IsNotExist(err) {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", workspace.Rel(s.root, sprintWorkspacePath(sp)), "unreadable sprint workspace", err.Error(), "Repair or remove the malformed sprint workspace record.")}
	}
	if !create {
		return source, nil
	}
	record, err = createSprintWorkspace(sp, source.Path, s.now().UTC())
	if err != nil {
		return ExecuteTargetRef{}, []ValidationFinding{finding("Sprint Workspace", "workspace", source.Path, "cannot create sprint workspace", err.Error(), "Commit or stash source changes, remove any conflicting branch or worktree, then retry.")}
	}
	return ExecuteTargetRef{Path: record.Path, Source: ".workspace.json"}, nil
}

func loadSprintWorkspace(sp Sprint) (SprintWorkspace, error) {
	data, err := os.ReadFile(sprintWorkspacePath(sp))
	if err != nil {
		return SprintWorkspace{}, err
	}
	var record SprintWorkspace
	if err := json.Unmarshal(data, &record); err != nil {
		return SprintWorkspace{}, fmt.Errorf("decode sprint workspace: %w", err)
	}
	if record.SchemaVersion != sprintWorkspaceSchemaVersion || record.SourceRoot == "" || record.Path == "" || record.Branch == "" || record.Baseline == "" {
		return SprintWorkspace{}, fmt.Errorf("invalid sprint workspace record")
	}
	return record, nil
}

func validateSprintWorkspace(record SprintWorkspace, source string) error {
	if filepath.Clean(record.SourceRoot) != filepath.Clean(source) {
		return fmt.Errorf("project target changed from %q to %q", record.SourceRoot, source)
	}
	info, err := os.Stat(record.Path)
	if err != nil {
		return fmt.Errorf("worktree unavailable: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("worktree path is not a directory")
	}
	sourceCommon, err := gitCommonDirectory(source)
	if err != nil {
		return fmt.Errorf("source Git metadata unavailable: %w", err)
	}
	workspaceCommon, err := gitCommonDirectory(record.Path)
	if err != nil || workspaceCommon != sourceCommon {
		return fmt.Errorf("worktree belongs to a different Git repository")
	}
	branch, err := gitOutput(record.Path, "branch", "--show-current")
	if err != nil || strings.TrimSpace(branch) != record.Branch {
		return fmt.Errorf("worktree is not on recorded branch %q", record.Branch)
	}
	return nil
}

func gitCommonDirectory(dir string) (string, error) {
	common, err := gitOutput(dir, "rev-parse", "--git-common-dir")
	if err != nil {
		return "", err
	}
	if !filepath.IsAbs(common) {
		common = filepath.Join(dir, common)
	}
	return filepath.Abs(filepath.Clean(common))
}

func createSprintWorkspace(sp Sprint, source string, now time.Time) (SprintWorkspace, error) {
	root, err := gitOutput(source, "rev-parse", "--show-toplevel")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("target is not a Git worktree: %w", err)
	}
	root = filepath.Clean(root)
	if filepath.Clean(source) != root {
		return SprintWorkspace{}, fmt.Errorf("target must be the Git worktree root %q", root)
	}
	dirty, err := gitOutput(source, "status", "--porcelain", "--untracked-files=normal")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("inspect target status: %w", err)
	}
	if strings.TrimSpace(dirty) != "" {
		return SprintWorkspace{}, fmt.Errorf("target has uncommitted changes")
	}
	baseline, err := gitOutput(source, "rev-parse", "HEAD")
	if err != nil {
		return SprintWorkspace{}, fmt.Errorf("resolve target HEAD: %w", err)
	}
	branch := "ultraplan/" + safeGitComponent(sp.Project) + "/" + safeGitComponent(sp.Slug)
	parent := filepath.Join(filepath.Dir(root), "."+filepath.Base(root)+"-ultraplan-worktrees")
	path := filepath.Join(parent, safeGitComponent(sp.Project), safeGitComponent(sp.Slug))
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		return SprintWorkspace{}, fmt.Errorf("worktree path already exists: %s", path)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return SprintWorkspace{}, fmt.Errorf("create worktree parent: %w", err)
	}
	cmd := exec.Command("git", "-C", source, "worktree", "add", "-b", branch, path, strings.TrimSpace(baseline))
	if output, err := cmd.CombinedOutput(); err != nil {
		return SprintWorkspace{}, fmt.Errorf("git worktree add: %s: %w", strings.TrimSpace(string(output)), err)
	}
	record := SprintWorkspace{SchemaVersion: sprintWorkspaceSchemaVersion, SourceRoot: root, Path: path, Branch: branch, Baseline: strings.TrimSpace(baseline), CreatedAt: now}
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return SprintWorkspace{}, err
	}
	data = append(data, '\n')
	if err := atomicWriteFile(sprintWorkspacePath(sp), data); err != nil {
		_ = exec.Command("git", "-C", source, "worktree", "remove", path).Run()
		_ = exec.Command("git", "-C", source, "branch", "-D", branch).Run()
		return SprintWorkspace{}, fmt.Errorf("persist sprint workspace: %w", err)
	}
	return record, nil
}

func gitOutput(dir string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
	}
	return strings.TrimSpace(string(output)), nil
}

func safeGitComponent(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	value = regexp.MustCompile(`[^a-z0-9._-]+`).ReplaceAllString(value, "-")
	value = strings.Trim(value, ".-")
	if value == "" {
		return "sprint"
	}
	return value
}

func ValidateExecuteWorkdir(target ExecuteTargetRef, workdir string) error {
	if target.Path == "" {
		return fmt.Errorf("missing execute target")
	}
	if workdir == "" {
		return fmt.Errorf("missing execute workdir")
	}
	targetPath := filepath.Clean(target.Path)
	workPath := filepath.Clean(workdir)
	if !filepath.IsAbs(workPath) {
		return fmt.Errorf("execute workdir %q must be absolute", workdir)
	}
	if !inside(targetPath, workPath) {
		return fmt.Errorf("execute workdir %q escapes approved target %q", workdir, target.Path)
	}
	return nil
}

func ExecuteSafetyInstructions(target ExecuteTargetRef) []string {
	return []string{
		"Work only inside approved target: " + target.Path,
		"Do not create smoke.md, smoke.json, generated review.md, issues.md, or issues.json.",
		"Do not run or request Git mutation: add, commit, push, branch, checkout, reset, PR creation, or issue tracking.",
		"Do not schedule cross-sprint work, launch a TUI, or build hosted/browser UI behavior.",
	}
}

func extractTargetImplementationDirectory(content string) string {
	re := regexp.MustCompile(`(?im)^\s*-\s+\*\*Target Implementation Directory:\*\*\s*(.+?)\s*$`)
	if match := re.FindStringSubmatch(content); len(match) == 2 {
		return strings.Trim(strings.TrimSpace(match[1]), "`")
	}
	re = regexp.MustCompile(`(?im)^\s*-\s+Target Implementation Directory:\s*(.+?)\s*$`)
	if match := re.FindStringSubmatch(content); len(match) == 2 {
		return strings.Trim(strings.TrimSpace(match[1]), "`")
	}
	return ""
}

