type gauntletSlowEventsRuntime struct{}

func (r *gauntletSlowEventsRuntime) StartRun(_ context.Context, _ agentwrap.RunRequest) (agentwrap.Run, error) {
	return &gauntletSlowRun{}, nil
}
func (r *gauntletSlowEventsRuntime) Capabilities(context.Context) (agentwrap.Capabilities, error) {
	return agentwrap.Capabilities{}, nil
}

type gauntletSlowRun struct {
	once sync.Once
	ch   chan agentwrap.Event
}

func (r *gauntletSlowRun) ID() agentwrap.RunID { return "slow-run" }
func (r *gauntletSlowRun) Events() <-chan agentwrap.Event {
	r.once.Do(func() {
		r.ch = make(chan agentwrap.Event, 1)
		r.ch <- agentwrap.Event{Payload: []byte(`{"type":"session","session_id":"late-session"}`)}
		close(r.ch)
	})
	return r.ch
}
func (r *gauntletSlowRun) Wait(context.Context) (agentwrap.RunResult, error) {
	time.Sleep(50 * time.Millisecond)
	return agentwrap.RunResult{SessionID: "late-session", Status: "success"}, nil
}
func (r *gauntletSlowRun) Cancel(context.Context) error { return nil }

// Reproduce: Adapter.StartRun returns after Wait while the event goroutine may
// still deliver OnEvent; Execute's post-run section mutates task/state without
// the session mutex.
func TestGauntletLateOnEventRacesTerminalPersist(t *testing.T) {
